script:
frappe.ui.form.on("Project", {
	__mks_task_tab_version: "2026-06-09T00:00Z-task-tab-ui-v29",

	refresh(frm) {
		if (!frm.is_new()) {
			frm.add_custom_button(__("Sync Tasks"), () => {
				frm.events.render_project_task_tab(frm);
				frappe.show_alert({ message: __("Task table synced"), indicator: "green" });
			}, __("Project Tasks"));
			frm.add_custom_button(__("Send Daily Task Summary"), () => {
				frappe.call({
					method: "milestoneksa.tasks.daily_task_summary.send_daily_task_summary_for_project",
					args: { project: frm.doc.name },
					callback(r) {
						if (r?.message) {
							frappe.show_alert({
								message: r.message.message || __("Daily task summary sent."),
								indicator: "green",
							});
						}
					},
					error(err) {
						frappe.msgprint({
							title: __("Error"),
							message: err.message || err.exc,
							indicator: "red",
						});
					},
				});
			}, __("Project Tasks"));
		}
		frm.events.render_project_task_tab(frm);
	},

	after_save(frm) {
		frm.events.render_project_task_tab(frm);
	},

	ensure_project_task_tab_styles() {
		const styleId = "mks-task-tab-styles-v29";
		if (document.getElementById(styleId)) return;
		const link = document.createElement("link");
		link.id = styleId;
		link.rel = "stylesheet";
		link.href = `/assets/milestoneksa/css/project_task_tab.css?v=29`;
		document.head.appendChild(link);
	},

	get_project_task_wrapper(frm) {
		const activeWrapper = frm.__project_task_active_wrapper;
		if (activeWrapper?.length && document.body.contains(activeWrapper.get(0))) {
			return activeWrapper;
		}
		return frm.fields_dict.custom_project_tasks_html?.$wrapper;
	},

	render_project_task_tab(frm, targetWrapper = null, options = {}) {
		frm.events.ensure_project_task_tab_styles();
		const field = frm.fields_dict.custom_project_tasks_html;
		if (!field) {
			frappe.msgprint({
				title: __("Setup Required"),
				message: __("Custom field 'custom_project_tasks_html' not found. Please reload the page."),
				indicator: "orange",
			});
			return;
		}

		const renderTarget = targetWrapper || frm.__project_task_render_target;
		const wrapper = renderTarget || field.$wrapper;
		const isFullscreen = Boolean(options.fullscreen || frm.__project_task_render_fullscreen);
		frm.__project_task_render_target = null;
		frm.__project_task_render_fullscreen = false;
		frm.__project_task_active_wrapper = wrapper;
		wrapper
			.empty()
			.addClass("project-task-tab-wrapper")
			.toggleClass("project-task-tab-wrapper--fullscreen", isFullscreen);

		if (frm.is_new()) {
			wrapper.append(
				$("<div class='text-muted small mt-2'>").text(
					__("Save the project to manage tasks from this tab.")
				)
			);
			return;
		}

		frm.__selected_task_names = new Set();
		if (!frm.__task_sort) {
			frm.__task_sort = { column: null, direction: "asc" };
		}

		const icon = (name) =>
			`<svg class="icon icon-sm"><use href="#icon-${name}"></use></svg>`;

		const header = $(`
			<div class="project-tasks-toolbar">
				<div class="project-tasks-toolbar__title-row">
					<div class="toolbar-title">${__("Project Tasks")}</div>
					<p class="text-muted small mb-0">
						${__("Click highlighted cells to edit inline. Parent tasks auto-update from children.")}
					</p>
				</div>
				<div class="project-tasks-toolbar__actions">
					<button class="btn btn-default btn-sm" data-role="delete-selected" disabled>
						${icon("delete")} ${__("Delete Selected")}
					</button>
					<button class="btn btn-default btn-sm" data-role="expand-all">${__("Expand All")}</button>
					<button class="btn btn-default btn-sm" data-role="collapse-all">${__("Collapse All")}</button>
					<button class="btn btn-default btn-sm" data-role="recalc-parents">
						${icon("refresh")} ${__("Recalc Parents")}
					</button>
					<button class="btn btn-default btn-sm" data-role="manage-columns">
						${icon("setting-gear")} ${__("Columns")}
					</button>
					${
						isFullscreen
							? ""
							: `<button class="btn btn-default btn-sm" data-role="open-fullscreen">
								${icon("maximize")} ${__("Full Screen")}
							</button>`
					}
					<button class="btn btn-primary btn-sm" data-role="add-task">
						${icon("add")} ${__("Add Task")}
					</button>
					<button class="btn btn-default btn-sm" data-role="refresh-tasks">
						${icon("refresh")} ${__("Refresh")}
					</button>
				</div>
				<div class="project-tasks-toolbar__filters">
					<label class="project-task-filter-check">
						<input type="checkbox" data-role="hide-completed">
						<span>${__("Hide Completed")}</span>
					</label>
					<label class="project-task-filter-select">
						<span>${__("Status")}</span>
						<select class="form-control form-control-sm" data-role="status-filter">
							<option value="">${__("All Statuses")}</option>
						</select>
					</label>
					<span class="text-muted small" data-role="filter-count"></span>
				</div>
			</div>
		`);

		const tableWrapper = $(`
			<div class="project-task-table-scroll">
				<table class="table table-bordered table-sm align-middle project-task-table mb-0">
					<thead><tr></tr></thead>
					<tbody></tbody>
				</table>
			</div>
		`);

		const emptyState = $(`
			<div class="d-none" data-role="empty">
				${icon("task").replace("icon-sm", "icon-xl text-muted mb-3")}
				<h5 class="text-muted">${__("No Tasks Yet")}</h5>
				<p class="text-muted mb-0">${__("Use Add Task to create your first task for this project.")}</p>
			</div>
		`);

		const loadingState = $(`
			<div class="text-center py-5" data-role="loading">
				<div class="spinner-border text-primary" role="status"></div>
				<div class="mt-3 text-muted">${__("Loading tasks...")}</div>
			</div>
		`);

		wrapper.append(header, tableWrapper, emptyState, loadingState);
		frm.events.build_project_task_table_header(frm, tableWrapper.find("thead tr"));

		header.find("[data-role='add-task']").on("click", () => frm.events.open_project_task_dialog(frm));
		header.find("[data-role='refresh-tasks']").on("click", () => frm.events.load_project_tasks(frm));
		header.find("[data-role='recalc-parents']").on("click", () => frm.events.recalculate_all_parents(frm));
		header.find("[data-role='manage-columns']").on("click", () => frm.events.open_project_task_column_dialog(frm));
		header.find("[data-role='open-fullscreen']").on("click", () => frm.events.open_project_task_fullscreen(frm));
		header.find("[data-role='expand-all']").on("click", () => frm.events.expand_all_tasks(frm));
		header.find("[data-role='collapse-all']").on("click", () => frm.events.collapse_all_tasks(frm));
		header.find("[data-role='delete-selected']").on("click", () => frm.events.delete_selected_tasks(frm));
		header.find("[data-role='hide-completed']").on("change", function () {
			frm.events.set_project_task_filter(frm, { hide_completed: $(this).prop("checked") });
		});
		header.find("[data-role='status-filter']").on("change", function () {
			frm.events.set_project_task_filter(frm, { status: $(this).val() || "" });
		});
		frm.events.update_project_task_filter_controls(frm, wrapper);

		wrapper.off(".projectTasks");
		wrapper.on("change.projectTasks", "[data-role='select-all']", function () {
			const isChecked = $(this).prop("checked");
			wrapper.find(".task-row-checkbox").prop("checked", isChecked).trigger("change");
		});

		wrapper.on("click.projectTasks", "thead th.sortable", function () {
			frm.events.toggle_project_task_sort(frm, $(this).data("column"));
		});
		wrapper.on("click.projectTasks", "[data-role='resize-column']", function (e) {
			e.preventDefault();
			e.stopPropagation();
		});
		wrapper.on("mousedown.projectTasks", "[data-role='resize-column']", function (e) {
			frm.events.start_project_task_column_resize(frm, e, $(this).data("column"));
		});

		frm.__project_task_load_target = wrapper;
		frm.events.load_project_tasks(frm);
	},

	open_project_task_fullscreen(frm) {
		const dialog = new frappe.ui.Dialog({
			title: __("Project Tasks"),
			fields: [{ fieldname: "task_table", fieldtype: "HTML" }],
		});

		dialog.show();
		dialog.$wrapper.addClass("project-task-fullscreen-modal");
		dialog.$wrapper.find(".modal-dialog").css({
			height: "calc(100vh - 24px)",
			margin: "12px auto",
			"max-width": "calc(100vw - 24px)",
			width: "calc(100vw - 24px)",
		});
		dialog.$wrapper.find(".modal-content").css("height", "100%");
		dialog.$wrapper.find(".modal-body").css({
			display: "flex",
			"flex-direction": "column",
			overflow: "hidden",
			padding: "12px",
		});

		const modalWrapper = dialog.fields_dict.task_table.$wrapper;
		modalWrapper.css({
			display: "flex",
			flex: "1 1 auto",
			"flex-direction": "column",
			"min-height": 0,
		});
		dialog.$wrapper
			.find(".form-layout, .form-page, .form-section, .section-body, .form-column, .form-column > form, .frappe-control, .control-input-wrapper, .control-value")
			.css({
				display: "flex",
				flex: "1 1 auto",
				"flex-direction": "column",
				"min-height": 0,
				width: "100%",
			});
		frm.__project_task_fullscreen_dialog = dialog;
		frm.__project_task_fullscreen_wrapper = modalWrapper;
		frm.__project_task_active_wrapper = modalWrapper;

		dialog.$wrapper.on("hidden.bs.modal", () => {
			if (frm.__project_task_active_wrapper?.get(0) === modalWrapper.get(0)) {
				frm.__project_task_active_wrapper = frm.fields_dict.custom_project_tasks_html?.$wrapper;
			}
			if (frm.__project_task_fullscreen_wrapper?.get(0) === modalWrapper.get(0)) {
				frm.__project_task_fullscreen_wrapper = null;
			}
			frm.events.render_project_task_tab(frm);
		});

		setTimeout(() => {
			frm.__project_task_render_target = modalWrapper;
			frm.__project_task_render_fullscreen = true;
			frm.__project_task_active_wrapper = modalWrapper;
			frm.events.render_project_task_tab(frm);
			modalWrapper.find(".project-task-table-scroll").css({
				flex: "1 1 auto",
				height: "calc(100vh - 230px)",
				"max-height": "calc(100vh - 230px)",
				"min-height": 0,
				"overflow-x": "auto",
				"overflow-y": "auto",
			});
			frm.events.ensure_fullscreen_tasks_loaded(frm, modalWrapper, 0);
		}, 100);
	},

	ensure_fullscreen_tasks_loaded(frm, modalWrapper, attempt = 0) {
		if (!modalWrapper?.length || !document.body.contains(modalWrapper.get(0))) return;
		const loadingVisible = modalWrapper.find("[data-role='loading']").is(":visible");
		const hasRows = modalWrapper.find("tbody tr").length > 0;
		if (!loadingVisible || hasRows) return;

		frm.__project_task_load_target = modalWrapper;
		frm.__project_task_active_wrapper = modalWrapper;
		frm.events.load_project_tasks(frm);

		if (attempt < 2) {
			setTimeout(() => frm.events.ensure_fullscreen_tasks_loaded(frm, modalWrapper, attempt + 1), 1200);
		}
	},

	get_project_task_columns() {
		return [
			{ id: "select", label: __("Select"), locked: true, minWidth: 36 },
			{ id: "subject", label: __("Task Name"), locked: true, minWidth: 420, sortable: true, sortField: "subject" },
			{ id: "wbs", label: __("WBS"), minWidth: 52, sortable: true, sortField: "wbs" },
			{ id: "status", label: __("Status"), minWidth: 86, sortable: true, sortField: "status", editable: true },
			{ id: "priority", label: __("Priority"), minWidth: 84, sortable: true, sortField: "priority", editable: true },
			{ id: "exp_start_date", label: __("Plan Start"), minWidth: 96, sortable: true, sortField: "exp_start_date", editable: true },
			{ id: "exp_end_date", label: __("Plan End"), minWidth: 96, sortable: true, sortField: "exp_end_date", editable: true },
			{ id: "duration_days", label: __("Duration"), minWidth: 76, sortable: true, sortField: "duration_days", defaultVisible: false },
			{ id: "planned_hours", label: __("Plan Hrs"), minWidth: 82, sortable: true, sortField: "planned_hours", editable: true, defaultVisible: false },
			{ id: "custom_actual_start_date", label: __("Actual Start"), minWidth: 98, sortable: true, sortField: "custom_actual_start_date", editable: true },
			{ id: "custom_actual_end_date", label: __("Actual End"), minWidth: 98, sortable: true, sortField: "custom_actual_end_date", editable: true },
			{ id: "actual_duration_days", label: __("Act. Dur."), minWidth: 82, sortable: true, sortField: "actual_duration_days", defaultVisible: false },
			{ id: "actual_hours", label: __("Act. Hrs"), minWidth: 82, sortable: true, sortField: "actual_hours", defaultVisible: false },
			{ id: "total_costing_amount", label: __("Cost"), minWidth: 92, sortable: true, sortField: "total_costing_amount", defaultVisible: false },
		];
	},

	build_project_task_table_header(frm, headerRow) {
		headerRow.empty();
		const columns = frm.events.get_project_task_columns();
		const sort = frm.__task_sort || {};
		const widths = frm.events.get_project_task_column_widths(frm);

		columns.forEach((column) => {
			const th = $(`<th data-column="${column.id}"></th>`);
			const width = widths[column.id] || column.minWidth;
			if (width) {
				th.css({
					"min-width": `${width}px`,
					width: `${width}px`,
					"max-width": column.id === "subject" ? `${Math.max(width, column.minWidth || width)}px` : "",
				});
			}

			if (column.id === "select") {
				th.append(
					$('<input type="checkbox" class="task-checkbox" data-role="select-all">').attr(
						"title",
						__("Select All")
					)
				);
			} else {
				const label = column.editable
					? `${column.label} <span class="column-editable-hint">${__("(editable)")}</span>`
					: column.label;
				th.html(label);
				if (column.sortable) {
					th.addClass("sortable").attr("data-column", column.id);
					const indicator =
						sort.column === column.id ? (sort.direction === "asc" ? "▲" : "▼") : "↕";
					const sortClass =
						sort.column === column.id
							? sort.direction === "asc"
								? "sorted-asc"
								: "sorted-desc"
							: "";
					th.addClass(sortClass);
					th.append(`<span class="sort-indicator">${indicator}</span>`);
				}
			}
			if (!column.locked || column.id === "subject") {
				th.append(
					$("<span>")
						.addClass("column-resize-handle")
						.attr("data-role", "resize-column")
						.attr("data-column", column.id)
						.attr("title", __("Drag to resize column"))
				);
			}
			headerRow.append(th);
		});
	},

	toggle_project_task_sort(frm, columnId) {
		const columns = frm.events.get_project_task_columns();
		const column = columns.find((c) => c.id === columnId);
		if (!column?.sortable) return;

		if (!frm.__task_sort) frm.__task_sort = { column: null, direction: "asc" };
		if (frm.__task_sort.column === columnId) {
			frm.__task_sort.direction = frm.__task_sort.direction === "asc" ? "desc" : "asc";
		} else {
			frm.__task_sort = { column: columnId, direction: "asc" };
		}

		const wrapper = frm.events.get_project_task_wrapper(frm);
		frm.events.build_project_task_table_header(frm, wrapper.find("thead tr"));
		if (frm.__project_tasks_data?.length) {
			const tableBody = wrapper.find("tbody");
			tableBody.empty();
			frm.events.render_task_hierarchy(frm, frm.__project_tasks_data, tableBody);
			frm.events.apply_project_task_column_preferences(frm);
		}
	},

	sort_sibling_tasks(frm, tasks) {
		const sort = frm.__task_sort || {};
		if (!sort.column || !tasks?.length) return tasks;

		const columns = frm.events.get_project_task_columns();
		const column = columns.find((c) => c.id === sort.column);
		if (!column?.sortField) return tasks;

		const field = column.sortField;
		const direction = sort.direction === "desc" ? -1 : 1;

		return tasks.slice().sort((a, b) => {
			let av = a[field];
			let bv = b[field];
			if (av == null || av === "") av = "";
			if (bv == null || bv === "") bv = "";
			if (typeof av === "number" || typeof bv === "number") {
				return ((parseFloat(av) || 0) - (parseFloat(bv) || 0)) * direction;
			}
			return String(av).localeCompare(String(bv), undefined, { numeric: true }) * direction;
		});
	},

	get_project_task_filter_key(frm) {
		return `mks_project_task_filters_${frm.doc.name || "new"}`;
	},

	get_project_task_filters(frm) {
		if (frm.__project_task_filters) return frm.__project_task_filters;
		const defaults = { hide_completed: false, status: "" };
		try {
			frm.__project_task_filters = {
				...defaults,
				...JSON.parse(localStorage.getItem(frm.events.get_project_task_filter_key(frm)) || "{}"),
			};
		} catch (e) {
			frm.__project_task_filters = defaults;
		}
		return frm.__project_task_filters;
	},

	save_project_task_filters(frm) {
		localStorage.setItem(
			frm.events.get_project_task_filter_key(frm),
			JSON.stringify(frm.events.get_project_task_filters(frm))
		);
	},

	is_completed_task_status(status) {
		return ["completed", "complete", "closed"].includes(String(status || "").trim().toLowerCase());
	},

	set_project_task_filter(frm, updates) {
		frm.__project_task_filters = {
			...frm.events.get_project_task_filters(frm),
			...updates,
		};
		frm.events.save_project_task_filters(frm);
		frm.events.update_project_task_filter_controls(frm);
		frm.events.apply_project_task_filters(frm);
	},

	update_project_task_filter_controls(frm, targetWrapper = null) {
		const wrapper = targetWrapper || frm.events.get_project_task_wrapper(frm);
		if (!wrapper?.length) return;

		const filters = frm.events.get_project_task_filters(frm);
		const select = wrapper.find("[data-role='status-filter']");
		const currentValue = filters.status || "";
		const options = frm.__project_task_meta?.status_options || [];

		select.empty().append($("<option>").val("").text(__("All Statuses")));
		options.forEach((status) => {
			select.append($("<option>").val(status).text(__(status)));
		});
		if (currentValue && !options.includes(currentValue)) {
			select.append($("<option>").val(currentValue).text(__(currentValue)));
		}

		wrapper.find("[data-role='hide-completed']").prop("checked", Boolean(filters.hide_completed));
		select.val(currentValue);
	},

	apply_project_task_filters(frm) {
		const wrapper = frm.events.get_project_task_wrapper(frm);
		if (!wrapper?.length || !frm.__project_tasks_data?.length) return;

		const tableBody = wrapper.find("tbody");
		const emptyState = wrapper.find("[data-role='empty']");
		emptyState.addClass("d-none");
		tableBody.empty();
		frm.events.render_task_hierarchy(frm, frm.__project_tasks_data, tableBody);
		frm.events.apply_project_task_column_preferences(frm);
		frm.events.update_select_all_checkbox(frm);
	},

	update_project_task_filter_count(frm, tableBody) {
		const wrapper = frm.events.get_project_task_wrapper(frm);
		if (!wrapper?.length) return;

		const total = frm.__project_tasks_data?.length || 0;
		const shown = tableBody.find("tr").length;
		const filters = frm.events.get_project_task_filters(frm);
		const hasFilter = Boolean(filters.hide_completed || filters.status);

		wrapper.find("[data-role='filter-count']").text(
			hasFilter ? __("{0} of {1} shown", [shown, total]) : ""
		);

		if (!shown && total) {
			wrapper.find("[data-role='empty']")
				.removeClass("d-none")
				.find("h5")
				.text(__("No Tasks Match Filters"));
			wrapper.find("[data-role='empty']")
				.find("p")
				.text(__("Change the status filter or uncheck Hide Completed to see more tasks."));
		}
	},

	save_task_expanded_state(frm) {
		const state = {};
		Object.entries(frm.__task_hierarchy || {}).forEach(([name, task]) => {
			if (task.expanded !== undefined) state[name] = task.expanded;
		});
		frm.__task_expanded_state = state;
	},

	get_task_expanded_state(frm, taskName) {
		if (frm.__task_expanded_state && taskName in frm.__task_expanded_state) {
			return frm.__task_expanded_state[taskName];
		}
		return true;
	},

	get_task_level_color(level) {
		const colors = [
			"var(--primary, #2490ef)",
			"var(--green-700, #13795b)",
			"var(--orange-700, #b25e09)",
			"var(--purple-700, #6f42c1)",
			"var(--cyan-700, #087990)",
			"var(--text-color, #1f272e)",
			"var(--text-color, #1f272e)",
		];
		return colors[Math.min(level, colors.length - 1)];
	},

	get_task_status_class(status) {
		const value = String(status || "").toLowerCase();
		if (["completed", "closed"].includes(value)) return "task-badge--green";
		if (["overdue"].includes(value)) return "task-badge--red";
		if (["working", "in progress"].includes(value)) return "task-badge--blue";
		if (["pending review"].includes(value)) return "task-badge--purple";
		if (["cancelled", "canceled"].includes(value)) return "task-badge--gray";
		return "task-badge--amber";
	},

	get_task_priority_class(priority) {
		const value = String(priority || "").toLowerCase();
		if (["urgent"].includes(value)) return "task-badge--red";
		if (["high"].includes(value)) return "task-badge--orange";
		if (["medium"].includes(value)) return "task-badge--blue";
		if (["low"].includes(value)) return "task-badge--green";
		return "task-badge--gray";
	},

	get_task_actual_date_class(value, task, dateField) {
		if (value) return "task-date-pill--set";
		const status = String(task.status || "").toLowerCase();
		if (status === "completed" && dateField === "custom_actual_end_date") return "task-date-pill--missing-danger";
		if (dateField === "custom_actual_start_date" && task.exp_start_date && frappe.datetime.get_diff(frappe.datetime.nowdate(), task.exp_start_date) > 0) {
			return "task-date-pill--missing-warning";
		}
		if (dateField === "custom_actual_end_date" && task.exp_end_date && frappe.datetime.get_diff(frappe.datetime.nowdate(), task.exp_end_date) > 0) {
			return "task-date-pill--missing-danger";
		}
		return "task-date-pill--missing";
	},

	get_project_task_column_preferences() {
		const columns = cur_frm.events.get_project_task_columns();
		const defaults = columns.map((column, index) => ({
			id: column.id,
			visible: column.locked || column.defaultVisible !== false,
			order: index + 1,
		}));
		const storageKey = "mks_project_task_columns_v2";

		try {
			const saved = JSON.parse(localStorage.getItem(storageKey) || "[]");
			const byId = {};
			saved.forEach((item) => {
				byId[item.id] = item;
			});
			return defaults.map((item) => ({
				...item,
				...(byId[item.id] || {}),
				visible: columns.find((c) => c.id === item.id)?.locked
					? true
					: byId[item.id]?.visible !== false,
			}));
		} catch (e) {
			return defaults;
		}
	},

	save_project_task_column_preferences(preferences) {
		localStorage.setItem("mks_project_task_columns_v2", JSON.stringify(preferences));
	},

	reset_project_task_column_preferences() {
		localStorage.removeItem("mks_project_task_columns_v2");
	},

	get_project_task_column_width_key(frm) {
		return `mks_project_task_column_widths_${frm.doc.name || "new"}`;
	},

	get_project_task_column_widths(frm) {
		try {
			return JSON.parse(localStorage.getItem(frm.events.get_project_task_column_width_key(frm)) || "{}");
		} catch (e) {
			return {};
		}
	},

	save_project_task_column_widths(frm, widths) {
		localStorage.setItem(frm.events.get_project_task_column_width_key(frm), JSON.stringify(widths || {}));
	},

	apply_project_task_column_width(frm, columnId, width) {
		const wrapper = frm.events.get_project_task_wrapper(frm);
		if (!wrapper?.length || !columnId || !width) return;

		const column = frm.events.get_project_task_columns().find((item) => item.id === columnId);
		const minWidth = column?.minWidth || 40;
		const nextWidth = Math.max(minWidth, Math.min(parseInt(width, 10) || minWidth, 900));
		const css = {
			"min-width": `${nextWidth}px`,
			width: `${nextWidth}px`,
		};
		if (columnId === "subject") {
			css["max-width"] = `${nextWidth}px`;
		}
		wrapper.find(`[data-column="${columnId}"]`).css(css);
	},

	start_project_task_column_resize(frm, event, columnId) {
		event.preventDefault();
		event.stopPropagation();
		const originalEvent = event.originalEvent || event;
		const wrapper = frm.events.get_project_task_wrapper(frm);
		const headerCell = wrapper?.find(`thead [data-column="${columnId}"]`);
		if (!headerCell?.length) return;

		const column = frm.events.get_project_task_columns().find((item) => item.id === columnId);
		const minWidth = column?.minWidth || 40;
		const startX = originalEvent.clientX;
		const startWidth = headerCell.outerWidth();
		$("body").addClass("project-task-column-resizing");

		const onMove = (moveEvent) => {
			const delta = (moveEvent.originalEvent || moveEvent).clientX - startX;
			const nextWidth = Math.max(minWidth, Math.min(startWidth + delta, 900));
			frm.events.apply_project_task_column_width(frm, columnId, nextWidth);
		};

		const onUp = () => {
			const widths = frm.events.get_project_task_column_widths(frm);
			widths[columnId] = Math.round(wrapper.find(`thead [data-column="${columnId}"]`).outerWidth());
			frm.events.save_project_task_column_widths(frm, widths);
			$("body").removeClass("project-task-column-resizing");
			$(document).off(".projectTaskColumnResize");
		};

		$(document)
			.on("mousemove.projectTaskColumnResize", onMove)
			.on("mouseup.projectTaskColumnResize", onUp);
	},

	apply_project_task_column_preferences(frm) {
		const wrapper = frm.events.get_project_task_wrapper(frm);
		if (!wrapper?.length) return;

		const columnsById = {};
		frm.events.get_project_task_columns().forEach((c) => {
			columnsById[c.id] = c;
		});

		const preferences = frm.events.get_project_task_column_preferences();
		const visibleById = {};
		const order = preferences
			.slice()
			.sort((a, b) => (parseInt(a.order, 10) || 0) - (parseInt(b.order, 10) || 0))
			.map((item) => {
				visibleById[item.id] = item.visible !== false;
				return item.id;
			});

		const reorderCells = (container) => {
			const cells = {};
			container.children("[data-column]").each(function () {
				const cell = $(this);
				cells[cell.data("column")] = cell.detach();
			});
			order.forEach((id) => {
				if (cells[id]) container.append(cells[id]);
			});
		};

		reorderCells(wrapper.find("thead tr"));
		wrapper.find("tbody tr").each(function () {
			reorderCells($(this));
		});

		Object.keys(visibleById).forEach((id) => {
			wrapper.find(`[data-column="${id}"]`).toggleClass("d-none", !visibleById[id]);
		});

		Object.keys(columnsById).forEach((id) => {
			const width = frm.events.get_project_task_column_widths(frm)[id] || columnsById[id].minWidth;
			if (width) frm.events.apply_project_task_column_width(frm, id, width);
		});
	},

	open_project_task_column_dialog(frm) {
		const columns = frm.events.get_project_task_columns();
		const preferences = frm.events.get_project_task_column_preferences();
		const byId = {};
		preferences.forEach((item) => {
			byId[item.id] = item;
		});

		const columnRows = columns
			.map((column, index) => {
				const pref = byId[column.id] || {};
				const visible = pref.visible !== false;
				const order = pref.order || index + 1;
				const disabled = column.locked ? "disabled" : "";
				const lockedLabel = column.locked ? `<span class="text-muted small">${__("Locked")}</span>` : "";
				return `
					<tr data-column-id="${frappe.utils.escape_html(column.id)}">
						<td class="text-center">
							<input type="checkbox" data-role="column-visible" ${visible ? "checked" : ""} ${disabled}>
						</td>
						<td>
							<div class="column-name">${column.label}</div>
							${lockedLabel}
						</td>
						<td>
							<input type="number" class="form-control form-control-sm" data-role="column-order"
								value="${order}" min="1" step="1">
						</td>
					</tr>
				`;
			})
			.join("");

		const dialog = new frappe.ui.Dialog({
			title: __("Manage Task Columns"),
			fields: [
				{
					fieldname: "columns_html",
					fieldtype: "HTML",
					options: `
						<div class="mks-task-column-manager">
							<div class="text-muted small mb-2">
								${__("Keep only important columns visible for a smaller, clearer task table.")}
							</div>
							<div class="table-responsive">
								<table class="table table-bordered table-sm mb-0">
									<thead>
										<tr>
											<th class="text-center">${__("Show")}</th>
											<th>${__("Column")}</th>
											<th>${__("Order")}</th>
										</tr>
									</thead>
									<tbody>${columnRows}</tbody>
								</table>
							</div>
						</div>
					`,
				},
			],
			primary_action_label: __("Apply"),
			primary_action() {
				const nextPreferences = [];
				dialog.$wrapper.find("[data-column-id]").each(function (index) {
					const row = $(this);
					const id = row.data("column-id");
					const column = columns.find((item) => item.id === id);
					nextPreferences.push({
						id,
						visible: column?.locked
							? true
							: row.find("[data-role='column-visible']").prop("checked"),
						order: parseInt(row.find("[data-role='column-order']").val(), 10) || index + 1,
					});
				});
				frm.events.save_project_task_column_preferences(nextPreferences);
				dialog.hide();
				frm.events.apply_project_task_column_preferences(frm);
			},
		});

		dialog.add_custom_action(__("Reset to Default"), () => {
			frm.events.reset_project_task_column_preferences();
			dialog.hide();
			frm.events.apply_project_task_column_preferences(frm);
			frappe.show_alert({ message: __("Column layout reset"), indicator: "green" });
		}, "btn-default");

		dialog.show();
	},

	expand_all_tasks(frm) {
		const wrapper = frm.events.get_project_task_wrapper(frm);
		const taskMap = frm.__task_hierarchy || {};
		Object.values(taskMap).forEach((task) => {
			if (task.children?.length) {
				task.expanded = true;
				const row = wrapper?.find(`tr[data-task="${task.name}"]`);
				row?.find(".collapse-triangle").removeClass("collapsed");
				row?.removeClass("collapsed");
			}
		});
		wrapper?.find("tr.child-task").removeClass("hidden-by-collapse").show();
		frappe.show_alert({ message: __("All tasks expanded"), indicator: "blue" }, 2);
	},

	collapse_all_tasks(frm) {
		const wrapper = frm.events.get_project_task_wrapper(frm);
		const taskMap = frm.__task_hierarchy || {};
		Object.values(taskMap).forEach((task) => {
			if (task.children?.length) {
				task.expanded = false;
				const row = wrapper?.find(`tr[data-task="${task.name}"]`);
				row?.find(".collapse-triangle").addClass("collapsed");
				row?.addClass("collapsed");
			}
		});
		wrapper?.find("tr.child-task").addClass("hidden-by-collapse").hide();
		frappe.show_alert({ message: __("All tasks collapsed"), indicator: "blue" }, 2);
	},

	recalculate_all_parents(frm) {
		frappe.call({
			method: "milestoneksa.api.project_tasks.recalculate_all_project_parents",
			args: { project: frm.doc.name },
			freeze: true,
			freeze_message: __("Recalculating parent tasks..."),
			callback: (r) => {
				if (r.message) {
					frappe.show_alert({
						message: __(`Updated ${r.message.updated_count} parent tasks`),
						indicator: "green",
					});
				}
				frm.events.load_project_tasks(frm);
			},
		});
	},

	load_project_tasks(frm) {
		const wrapper = frm.__project_task_load_target || frm.events.get_project_task_wrapper(frm);
		frm.__project_task_load_target = null;
		if (!wrapper?.length) return;
		frm.__project_task_active_wrapper = wrapper;

		frm.events.save_task_expanded_state(frm);

		frm.__selected_task_names = new Set();
		wrapper.find("[data-role='select-all']").prop("checked", false).prop("indeterminate", false);
		wrapper.find("[data-role='delete-selected']").prop("disabled", true);

		const tableBody = wrapper.find("tbody");
		const emptyState = wrapper.find("[data-role='empty']");
		const loadingState = wrapper.find("[data-role='loading']");

		tableBody.empty();
		emptyState.addClass("d-none");
		loadingState.removeClass("d-none");

		frappe.call({
			method: "milestoneksa.api.project_tasks.get_project_tasks",
			args: { project: frm.doc.name },
			callback: (r) => {
				loadingState.addClass("d-none");

				if (!r?.message) {
					emptyState.removeClass("d-none");
					return;
				}

				const { tasks = [], currency, status_options = [], priority_options = [] } = r.message;
				frm.__project_task_meta = { currency, status_options, priority_options };

				if (!tasks.length) {
					emptyState.removeClass("d-none");
					return;
				}

				frm.__project_tasks_data = tasks;
				frm.events.update_project_task_filter_controls(frm, wrapper);
				frm.events.render_task_hierarchy(frm, tasks, tableBody);
				frm.events.apply_project_task_column_preferences(frm);
				frm.events.update_select_all_checkbox(frm);
			},
			error: () => {
				loadingState.addClass("d-none");
				emptyState.removeClass("d-none");
				frappe.msgprint({
					title: __("Error Loading Tasks"),
					message: __("Unable to load tasks. Please try again."),
					indicator: "red",
				});
			},
		});
	},

	render_task_hierarchy(frm, tasks, tableBody) {
		const taskMap = {};
		const rootTasks = [];
		const filters = frm.events.get_project_task_filters(frm);
		const visibleTaskNames = new Set();

		tasks.forEach((t) => {
			taskMap[t.name] = {
				...t,
				children: [],
				expanded: frm.events.get_task_expanded_state(frm, t.name),
			};
		});

		tasks.forEach((t) => {
			if (t.parent_task && taskMap[t.parent_task]) {
				taskMap[t.parent_task].children.push(taskMap[t.name]);
			} else {
				rootTasks.push(taskMap[t.name]);
			}
		});

		frm.__task_hierarchy = taskMap;

		const taskMatchesFilters = (task) => {
			if (filters.hide_completed && frm.events.is_completed_task_status(task.status)) return false;
			if (filters.status && task.status !== filters.status) return false;
			return true;
		};

		const markVisibleWithAncestors = (task) => {
			let current = task;
			while (current?.name && !visibleTaskNames.has(current.name)) {
				visibleTaskNames.add(current.name);
				current = current.parent_task ? taskMap[current.parent_task] : null;
			}
		};

		tasks.forEach((task) => {
			const taskNode = taskMap[task.name];
			if (taskNode && taskMatchesFilters(taskNode)) {
				markVisibleWithAncestors(taskNode);
			}
		});

		const sortChildren = (list) => {
			const sorted = frm.events.sort_sibling_tasks(frm, list);
			sorted.forEach((task) => {
				if (task.children?.length) task.children = sortChildren(task.children);
			});
			return sorted;
		};

		const sortedRoots = sortChildren(rootTasks);

		function renderTask(task, level = 0, parentExpanded = true) {
			if (!visibleTaskNames.has(task.name)) return;

			const row = frm.events.render_project_task_row(frm, task, level);
			tableBody.append(row);

			if (!parentExpanded || !task.expanded) {
				if (level > 0) row.addClass("hidden-by-collapse").hide();
			}

			if (task.children?.length) {
				task.children.forEach((child) => {
					renderTask(child, level + 1, parentExpanded && task.expanded);
				});
			}
		}

		sortedRoots.forEach((task) => renderTask(task, 0, true));
		frm.events.update_project_task_filter_count(frm, tableBody);
	},

	render_project_task_row(frm, task, level = 0) {
		const currency = frm.__project_task_meta?.currency;
		const meta = frm.__project_task_meta || {};
		const hasChildren = task.children?.length > 0;
		const indent = level * 40;
		const levelClass = `task-level-${Math.min(level, 6)}`;
		const rowClass = `${hasChildren ? "parent-task-row" : "child-task"} ${levelClass}`;

		const toUserDate = (value) => (value ? frappe.datetime.str_to_user(value) : "-");
		const badge = (value, cls) =>
			`<span class="task-badge ${cls}">${frappe.utils.escape_html(value ? __(value) : "-")}</span>`;
		const actualDatePill = (value, field) => {
			const cls = frm.events.get_task_actual_date_class(value, task, field);
			return `<span class="task-date-pill ${cls}">${toUserDate(value)}</span>`;
		};
		const toDays = (value) => (value == null || isNaN(value) ? "-" : `${value} ${__("days")}`);
		const toHours = (value) =>
			value == null ? "-" : frappe.format(value, { fieldtype: "Float", precision: 2 });
		const toCurrency = (value) =>
			value == null ? "-" : frappe.format(value, { fieldtype: "Currency", options: currency });

		const row = $(`
			<tr data-task="${frappe.utils.escape_html(task.name)}"
			    data-parent="${frappe.utils.escape_html(task.parent_task || "")}"
			    data-level="${level}"
			    class="${rowClass}">
				<td data-column="select">
					<input type="checkbox" class="task-checkbox task-row-checkbox" data-task="${frappe.utils.escape_html(task.name)}">
				</td>
				<td data-column="subject" class="task-subject" style="--task-indent: ${indent}px;"></td>
				<td data-column="wbs">${frappe.utils.escape_html(task.wbs || "")}</td>
				<td data-column="status" class="editable-cell" data-field="status">${badge(task.status, frm.events.get_task_status_class(task.status))}</td>
				<td data-column="priority" class="editable-cell" data-field="priority">${badge(task.priority, frm.events.get_task_priority_class(task.priority))}</td>
				<td data-column="exp_start_date" class="editable-cell" data-field="exp_start_date">${toUserDate(task.exp_start_date)}</td>
				<td data-column="exp_end_date" class="editable-cell" data-field="exp_end_date">${toUserDate(task.exp_end_date)}</td>
				<td data-column="duration_days">${toDays(task.duration_days)}</td>
				<td data-column="planned_hours" class="editable-cell" data-field="planned_hours">${toHours(task.planned_hours)}</td>
				<td data-column="custom_actual_start_date" class="editable-cell" data-field="custom_actual_start_date">${actualDatePill(task.custom_actual_start_date, "custom_actual_start_date")}</td>
				<td data-column="custom_actual_end_date" class="editable-cell" data-field="custom_actual_end_date">${actualDatePill(task.custom_actual_end_date, "custom_actual_end_date")}</td>
				<td data-column="actual_duration_days">${toDays(task.actual_duration_days)}</td>
				<td data-column="actual_hours">${toHours(task.actual_hours)}</td>
				<td data-column="total_costing_amount">${toCurrency(task.total_costing_amount)}</td>
			</tr>
		`);

		const subjectCell = row.find(".task-subject");
		const subjectInner = $('<div class="task-subject-inner"></div>');
		const titleWrap = $('<div class="task-subject-title"></div>');
		subjectInner.css("align-items", "flex-start");
		titleWrap.css({
			"align-items": "flex-start",
			"flex-wrap": "wrap",
			overflow: "visible",
		});
		const actions = $(`
			<span class="task-actions-group">
				<span class="task-drag-handle" draggable="true" data-role="drag-task" title="${__("Drag to reorder inside this parent")}">⋮⋮</span>
				<button class="btn btn-link btn-sm" data-role="add-child" title="${__("Add Child Task")}">
					<svg class="icon icon-sm"><use href="#icon-add"></use></svg>
				</button>
				<button class="btn btn-link btn-sm" data-role="edit-task" title="${__("Edit")}">
					<svg class="icon icon-sm"><use href="#icon-edit"></use></svg>
				</button>
				<button class="btn btn-link btn-sm text-danger" data-role="delete-task" title="${__("Delete Task")}">
					<svg class="icon icon-sm"><use href="#icon-delete"></use></svg>
				</button>
			</span>
		`);

		if (hasChildren) {
			const triangle = $(`<span class="collapse-triangle${task.expanded ? "" : " collapsed"}">▼</span>`);
			triangle.on("click", (e) => {
				e.stopPropagation();
				frm.events.toggle_task_children(frm, task.name);
			});
			titleWrap.append(triangle);
		} else {
			titleWrap.append($('<span class="collapse-triangle-spacer" style="width:18px;display:inline-block;"></span>'));
		}
		if (level > 0) {
			titleWrap.append(
				$('<span class="task-level-marker"></span>')
					.text(level)
					.css("border-color", frm.events.get_task_level_color(level))
					.css("color", frm.events.get_task_level_color(level))
			);
		}

		const link = $(`<a class="${hasChildren ? "fw-bold" : ""}">`)
			.text(task.subject || task.name)
			.css({
				color: frm.events.get_task_level_color(level),
				flex: "1 1 auto",
				"line-height": "1.35",
				"min-width": 0,
				overflow: "visible",
				"overflow-wrap": "anywhere",
				"text-overflow": "clip",
				"white-space": "normal",
				"word-break": "break-word",
			})
			.on("click", () => frappe.set_route("Form", "Task", task.name));
		titleWrap.append(link);
		subjectInner.append(titleWrap, actions);
		subjectCell.append(subjectInner);

		row.find(".editable-cell").on("click", function () {
			frm.events.make_cell_editable(frm, $(this), task, meta);
		});

		row.find("[data-role='add-child']").on("click", () => frm.events.open_project_task_dialog(frm, null, task.name));
		row.find("[data-role='drag-task']").on("dragstart", (e) => frm.events.start_task_drag(frm, e, task.name));
		row.find("[data-role='edit-task']").on("click", () => frm.events.open_project_task_dialog(frm, task));
		row.find("[data-role='delete-task']").on("click", () => frm.events.delete_single_task(frm, task));
		row.on("dragover", (e) => frm.events.drag_over_task_row(frm, e, task.name));
		row.on("dragleave", () => row.removeClass("drag-over-top drag-over-bottom"));
		row.on("drop", (e) => frm.events.drop_task_on_row(frm, e, task.name));
		row.on("dragend", () => frm.events.clear_task_drag_state(frm));

		row.find(".task-row-checkbox").on("change", function () {
			const isChecked = $(this).prop("checked");
			const taskName = $(this).data("task");
			if (!frm.__selected_task_names) frm.__selected_task_names = new Set();
			if (isChecked) frm.__selected_task_names.add(taskName);
			else frm.__selected_task_names.delete(taskName);
			row.toggleClass("task-row-selected", isChecked);
			frm.events.update_select_all_checkbox(frm);
		});

		return row;
	},

	toggle_task_children(frm, taskName) {
		const task = (frm.__task_hierarchy || {})[taskName];
		if (!task?.children?.length) return;

		task.expanded = !task.expanded;
		const wrapper = frm.events.get_project_task_wrapper(frm);
		const row = wrapper?.find(`tr[data-task="${taskName}"]`);
		const triangle = row?.find(".collapse-triangle");

		if (task.expanded) {
			triangle?.removeClass("collapsed");
			row?.removeClass("collapsed");
		} else {
			triangle?.addClass("collapsed");
			row?.addClass("collapsed");
		}

		function toggleDescendants(parentTask, show) {
			parentTask.children.forEach((child) => {
				const childRow = wrapper?.find(`tr[data-task="${child.name}"]`);
				if (show && task.expanded) {
					childRow?.removeClass("hidden-by-collapse").show();
					if (child.expanded && child.children?.length) toggleDescendants(child, true);
				} else {
					childRow?.addClass("hidden-by-collapse").hide();
					if (child.children?.length) toggleDescendants(child, false);
				}
			});
		}

		toggleDescendants(task, task.expanded);
	},

	start_task_drag(frm, event, taskName) {
		const originalEvent = event.originalEvent || event;
		const task = (frm.__task_hierarchy || {})[taskName];
		if (!task) return;

		frm.__dragged_task_name = taskName;
		frm.__dragged_parent_task = task.parent_task || "";
		frm.events.save_task_expanded_state(frm);

		if (originalEvent.dataTransfer) {
			originalEvent.dataTransfer.effectAllowed = "move";
			originalEvent.dataTransfer.setData("text/plain", taskName);
		}
		$(originalEvent.target).closest("tr").addClass("dragging");
	},

	drag_over_task_row(frm, event, targetTaskName) {
		const draggedTaskName = frm.__dragged_task_name;
		if (!draggedTaskName || draggedTaskName === targetTaskName) return;

		const taskMap = frm.__task_hierarchy || {};
		const dragged = taskMap[draggedTaskName];
		const target = taskMap[targetTaskName];
		if (!dragged || !target || (dragged.parent_task || "") !== (target.parent_task || "")) return;

		event.preventDefault();
		const originalEvent = event.originalEvent || event;
		const row = $(originalEvent.currentTarget);
		const rect = originalEvent.currentTarget.getBoundingClientRect();
		const isAfter = originalEvent.clientY > rect.top + rect.height / 2;
		row.toggleClass("drag-over-top", !isAfter).toggleClass("drag-over-bottom", isAfter);
		if (originalEvent.dataTransfer) originalEvent.dataTransfer.dropEffect = "move";
	},

	drop_task_on_row(frm, event, targetTaskName) {
		const draggedTaskName = frm.__dragged_task_name;
		frm.events.clear_task_drag_state(frm);
		if (!draggedTaskName || draggedTaskName === targetTaskName) return;

		const originalEvent = event.originalEvent || event;
		event.preventDefault();

		const taskMap = frm.__task_hierarchy || {};
		const dragged = taskMap[draggedTaskName];
		const target = taskMap[targetTaskName];
		if (!dragged || !target) return;

		const parentTask = dragged.parent_task || "";
		if (parentTask !== (target.parent_task || "")) {
			frappe.show_alert({
				message: __("Tasks can only be reordered inside the same parent group."),
				indicator: "orange",
			});
			return;
		}

		const wrapper = frm.events.get_project_task_wrapper(frm);
		const orderedNames = wrapper
			?.find("tbody tr")
			.filter(function () {
				return ($(this).data("parent") || "") === parentTask;
			})
			.map(function () {
				return $(this).data("task");
			})
			.get()
			.filter((name) => name && name !== draggedTaskName);
		const targetIndex = orderedNames.indexOf(targetTaskName);
		if (targetIndex === -1) return;

		const rect = originalEvent.currentTarget.getBoundingClientRect();
		const isAfter = originalEvent.clientY > rect.top + rect.height / 2;
		orderedNames.splice(targetIndex + (isAfter ? 1 : 0), 0, draggedTaskName);

		frm.__task_sort = { column: null, direction: "asc" };
		frm.events.reorder_project_task_siblings(frm, parentTask, orderedNames);
	},

	clear_task_drag_state(frm) {
		const wrapper = frm.events.get_project_task_wrapper(frm);
		wrapper?.find("tr").removeClass("dragging drag-over-top drag-over-bottom");
		frm.__dragged_task_name = null;
		frm.__dragged_parent_task = null;
	},

	make_cell_editable(frm, cell, task, meta) {
		if (cell.data("editing")) return;
		cell.data("editing", true);

		const field = cell.data("field");
		const currentValue = task[field];
		const originalHtml = cell.html();
		cell.empty().css("padding", "2px");

		let input;
		let dateControl = null;
		let dateWrapper = null;
		let clearDateButton = null;
		let saveDateButton = null;
		let dateValueChanged = false;
		let cleanupEditEvents = () => {};
		if (field === "status") {
			input = $(`<select class="form-control form-control-sm"></select>`);
			(meta.status_options || []).forEach((opt) => {
				input.append($("<option>").val(opt).text(__(opt)).prop("selected", opt === currentValue));
			});
		} else if (field === "priority") {
			input = $(`<select class="form-control form-control-sm"></select>`);
			(meta.priority_options || []).forEach((opt) => {
				input.append($("<option>").val(opt).text(__(opt)).prop("selected", opt === currentValue));
			});
		} else if (
			["exp_start_date", "exp_end_date", "custom_actual_start_date", "custom_actual_end_date"].includes(field)
		) {
			dateWrapper = $(`<div class="inline-date-control"></div>`);
			cell.append(dateWrapper);
			dateControl = frappe.ui.form.make_control({
				parent: dateWrapper,
				df: {
					fieldtype: "Date",
					fieldname: `inline_${field}`,
					label: "",
					default: currentValue || "",
				},
				render_input: true,
			});
			dateControl.set_value(currentValue || "");
			input = dateControl.$input || dateWrapper.find("input");
			input
				.addClass("form-control-sm")
				.attr("placeholder", frappe.datetime.str_to_user(frappe.datetime.nowdate()))
				.attr("autocomplete", "off")
				.prop("readonly", false);
			const dateActions = $(`
				<div class="inline-date-actions">
					<button type="button" class="btn btn-xs btn-default" data-role="clear-date">${__("Clear")}</button>
					<button type="button" class="btn btn-xs btn-primary" data-role="save-date">${__("Save")}</button>
				</div>
			`);
			dateWrapper.append(dateActions);
			clearDateButton = dateActions.find("[data-role='clear-date']");
			saveDateButton = dateActions.find("[data-role='save-date']");
		} else if (field === "planned_hours") {
			input = $(`<input type="number" step="0.5" class="form-control form-control-sm">`);
			input.val(currentValue || "");
		}

		if (!dateControl) {
			cell.append(input);
		}
		setTimeout(() => {
			input.focus();
			if (dateControl && input.trigger) {
				input.prop("readonly", false).removeAttr("readonly");
				input.trigger("click");
			}
		}, 50);

		let saved = false;
		const getDateInputValue = () => {
			if (!dateControl) return "";
			const rawValue = (input.val() || "").trim();
			if (!rawValue) return "";
			try {
				return frappe.datetime.user_to_str(rawValue) || dateControl.get_value() || rawValue;
			} catch (e) {
				return dateControl.get_value() || rawValue;
			}
		};
		const saveValue = () => {
			if (saved) return;
			saved = true;
			cleanupEditEvents();
			const newValue = dateControl ? getDateInputValue() : input.val();
			const normalizedCurrentValue = currentValue || "";
			cell.data("editing", false).css("padding", "");
			if (dateControl && !dateValueChanged) {
				cell.html(originalHtml);
				return;
			}
			if (newValue !== normalizedCurrentValue) {
				const updates = {};
				updates[field] = newValue;
				cell.html(`<span class="text-muted"><i>${__("Saving...")}</i></span>`);
				frm.events.quick_update_task(frm, task.name, updates);
			} else {
				cell.html(originalHtml);
			}
		};
		const cancelEdit = () => {
			if (saved) return;
			saved = true;
			cleanupEditEvents();
			cell.data("editing", false).css("padding", "").html(originalHtml);
		};

		if (dateControl) {
			const enableDateTyping = () => {
				input.prop("readonly", false).removeAttr("readonly");
			};
			enableDateTyping();
			setTimeout(enableDateTyping, 150);
			setTimeout(enableDateTyping, 500);

			input.on("change input", () => {
				enableDateTyping();
				dateValueChanged = true;
			});
			input.on("focus click mousedown", enableDateTyping);
			input.on("keydown", (e) => {
				if (e.which === 13) {
					e.preventDefault();
					dateValueChanged = true;
					saveValue();
				} else if (e.which === 27) {
					e.preventDefault();
					cancelEdit();
				}
			});
			dateWrapper.on("mousedown click", (e) => e.stopPropagation());
			const editNamespace = `.projectTaskInlineDate${Date.now()}${Math.floor(Math.random() * 10000)}`;
			const isDatePickerElement = (target) =>
				$(target).closest(".flatpickr-calendar, .datepicker, .ui-datepicker, .dropdown-menu").length > 0;
			$(document).on(`mousedown${editNamespace}`, (e) => {
				if (saved) return;
				if (dateWrapper.get(0).contains(e.target) || isDatePickerElement(e.target)) return;
				dateValueChanged ? saveValue() : cancelEdit();
			});
			cleanupEditEvents = () => $(document).off(editNamespace);
			clearDateButton.on("mousedown", (e) => e.preventDefault());
			clearDateButton.on("click", (e) => {
				e.preventDefault();
				dateValueChanged = true;
				dateControl.set_value("");
				input.val("");
				saveValue();
			});
			saveDateButton.on("mousedown", (e) => e.preventDefault());
			saveDateButton.on("click", (e) => {
				e.preventDefault();
				dateValueChanged = true;
				saveValue();
			});
		} else if (input.is("select")) {
			input.on("change", saveValue);
			input.on("blur", () => setTimeout(cancelEdit, 100));
		} else {
			input.on("blur", () => setTimeout(saveValue, 100));
			input.on("keydown", (e) => {
				if (e.which === 13) {
					e.preventDefault();
					saveValue();
				} else if (e.which === 27) {
					e.preventDefault();
					cancelEdit();
				}
			});
		}
		input.on("click", (e) => e.stopPropagation());
	},

	quick_update_task(frm, taskName, updates) {
		frappe.call({
			method: "milestoneksa.api.project_tasks.update_project_task",
			args: { task_name: taskName, updates },
			freeze: false,
			callback: () => {
				frappe.show_alert({ message: __("Task updated"), indicator: "green" });
				frm.events.load_project_tasks(frm);
			},
		});
	},

	reorder_project_task(frm, taskName, direction) {
		frm.events.save_task_expanded_state(frm);
		frappe.call({
			method: "milestoneksa.api.project_tasks.reorder_project_task",
			args: { task_name: taskName, direction },
			freeze: false,
			callback: (r) => {
				frappe.show_alert({
					message: r?.message?.moved
						? __("Task order updated")
						: __("Task is already at the edge of this group"),
					indicator: r?.message?.moved ? "green" : "orange",
				});
				frm.events.load_project_tasks(frm);
			},
		});
	},

	reorder_project_task_siblings(frm, parentTask, orderedNames) {
		frm.events.save_task_expanded_state(frm);
		frappe.call({
			method: "milestoneksa.api.project_tasks.reorder_project_task_siblings",
			args: {
				project: frm.doc.name,
				parent_task: parentTask || "",
				task_names: orderedNames,
			},
			freeze: false,
			callback: () => {
				frm.__task_sort = { column: null, direction: "asc" };
				const wrapper = frm.events.get_project_task_wrapper(frm);
				if (wrapper?.length) frm.events.build_project_task_table_header(frm, wrapper.find("thead tr"));
				frappe.show_alert({ message: __("Task order updated"), indicator: "green" });
				frm.events.load_project_tasks(frm);
			},
			error: () => {
				frappe.msgprint({
					title: __("Unable to Reorder"),
					message: __("Tasks can only be dragged within the same parent group."),
					indicator: "orange",
				});
				frm.events.load_project_tasks(frm);
			},
		});
	},

	open_project_task_dialog(frm, task = null, parentTask = null) {
		const isEdit = Boolean(task);
		const meta = frm.__project_task_meta || {};
		const statusOptions = meta.status_options || ["Open", "Working", "Pending Review", "Overdue", "Completed", "Cancelled"];
		const priorityOptions = meta.priority_options || ["Low", "Medium", "High", "Urgent"];

		const dialog = new frappe.ui.Dialog({
			title: isEdit ? __("Update Task") : parentTask ? __("Add Child Task") : __("Add Task"),
			fields: [
				{ fieldname: "subject", label: __("Subject"), fieldtype: "Data", reqd: 1 },
				{
					fieldname: "is_group",
					label: __("Is Group (Parent Task)"),
					fieldtype: "Check",
					default: 0,
					description: __("Check this if this task will have child tasks"),
				},
				{ fieldname: "status", label: __("Status"), fieldtype: "Select", options: statusOptions.join("\n"), default: "Open" },
				{ fieldname: "priority", label: __("Priority"), fieldtype: "Select", options: priorityOptions.join("\n"), default: "Medium" },
				{ fieldname: "col_break_1", fieldtype: "Column Break" },
				{ fieldname: "exp_start_date", label: __("Planned Start"), fieldtype: "Date" },
				{ fieldname: "exp_end_date", label: __("Planned Finish"), fieldtype: "Date" },
				{ fieldname: "planned_hours", label: __("Planned Hours"), fieldtype: "Float" },
				{ fieldname: "section_actual", label: __("Actual Dates"), fieldtype: "Section Break" },
				{ fieldname: "custom_actual_start_date", label: __("Actual Start Date"), fieldtype: "Date" },
				{ fieldname: "col_break_2", fieldtype: "Column Break" },
				{ fieldname: "custom_actual_end_date", label: __("Actual End Date"), fieldtype: "Date" },
				{ fieldname: "section_more", label: __("More Details"), fieldtype: "Section Break", collapsible: 1 },
				{
					fieldname: "parent_task",
					label: __("Parent Task"),
					fieldtype: "Link",
					options: "Task",
					description: __("Optional: link this task beneath another task in this project."),
					default: parentTask || "",
					read_only: parentTask ? 1 : 0,
				},
				{ fieldname: "description", label: __("Description"), fieldtype: "Small Text" },
			],
			primary_action_label: isEdit ? __("Update") : __("Create"),
			primary_action(values) {
				if (!values.subject) {
					frappe.msgprint(__("Subject is required."));
					return;
				}
				if (parentTask) values.parent_task = parentTask;
				if (isEdit) frm.events.submit_task_update(frm, task.name, values, dialog);
				else frm.events.submit_task_create(frm, values, dialog);
			},
		});

		if (isEdit) {
			dialog.set_values({
				subject: task.subject,
				is_group: task.is_group || 0,
				status: task.status,
				priority: task.priority,
				exp_start_date: task.exp_start_date,
				exp_end_date: task.exp_end_date,
				planned_hours: task.planned_hours,
				custom_actual_start_date: task.custom_actual_start_date,
				custom_actual_end_date: task.custom_actual_end_date,
				parent_task: task.parent_task,
				description: task.description,
			});
			dialog.add_custom_action(__("Delete"), () => frm.events.delete_single_task(frm, task, dialog), "btn-danger");
		}

		dialog.fields_dict.parent_task.get_query = () => ({ filters: { project: frm.doc.name } });
		dialog.show();
	},

	submit_task_create(frm, values, dialog) {
		frappe.call({
			method: "milestoneksa.api.project_tasks.create_project_task",
			args: { project: frm.doc.name, task: values },
			freeze: true,
			freeze_message: __("Creating task..."),
			callback: () => {
				dialog.hide();
				frappe.show_alert({ message: __("Task created"), indicator: "green" });
				frm.events.load_project_tasks(frm);
			},
		});
	},

	submit_task_update(frm, taskName, values, dialog) {
		frappe.call({
			method: "milestoneksa.api.project_tasks.update_project_task",
			args: { task_name: taskName, updates: values },
			freeze: true,
			freeze_message: __("Updating task..."),
			callback: () => {
				dialog.hide();
				frappe.show_alert({ message: __("Task updated"), indicator: "green" });
				frm.events.load_project_tasks(frm);
			},
		});
	},

	delete_selected_tasks(frm) {
		const selected = Array.from(frm.__selected_task_names || []);
		if (!selected.length) {
			frappe.msgprint({
				title: __("No Tasks Selected"),
				message: __("Please select at least one task to delete."),
				indicator: "orange",
			});
			return;
		}

		frappe.confirm(
			__(
				"Are you sure you want to delete {0} selected task(s)? Child tasks must be selected separately. This action cannot be undone.",
				[selected.length]
			),
			() => {
				frappe.call({
					method: "milestoneksa.api.project_tasks.delete_project_tasks",
					args: { task_names: selected, force: 1, delete_connected: 0 },
					freeze: true,
					freeze_message: __("Deleting tasks..."),
					callback: (r) => {
						frappe.show_alert({
							message: __("{0} selected task(s) deleted successfully", [r?.message?.deleted_count ?? selected.length]),
							indicator: "green",
						});
						frm.events.load_project_tasks(frm);
					},
				});
			}
		);
	},

	delete_single_task(frm, task, dialog = null) {
		if (!task?.name) return;
		const taskSubject = task.subject || task.name;

		frappe.confirm(
			__(
				"Are you sure you want to delete the task '{0}'? Child tasks must be deleted first. This action cannot be undone.",
				[taskSubject]
			),
			() => {
				if (dialog) dialog.hide();
				frappe.call({
					method: "milestoneksa.api.project_tasks.delete_project_tasks",
					args: { task_names: [task.name], force: 1, delete_connected: 0 },
					freeze: true,
					freeze_message: __("Deleting task..."),
					callback: (r) => {
						frappe.show_alert({
							message: __("Deleted {0} task(s)", [r?.message?.deleted_count ?? 1]),
							indicator: "green",
						});
						frm.events.load_project_tasks(frm);
					},
				});
			}
		);
	},

	update_select_all_checkbox(frm) {
		const wrapper = frm.events.get_project_task_wrapper(frm);
		if (!wrapper?.length) return;

		const allCheckboxes = wrapper.find(".task-row-checkbox");
		const checkedCheckboxes = wrapper.find(".task-row-checkbox:checked");
		const selectAllCheckbox = wrapper.find("[data-role='select-all']");
		const deleteBtn = wrapper.find("[data-role='delete-selected']");

		frm.__selected_task_names = new Set(
			checkedCheckboxes.map(function () {
				return $(this).data("task");
			}).get()
		);

		deleteBtn.prop("disabled", checkedCheckboxes.length === 0);

		if (!allCheckboxes.length) {
			selectAllCheckbox.prop("checked", false).prop("indeterminate", false);
			return;
		}

		if (checkedCheckboxes.length === 0) {
			selectAllCheckbox.prop("indeterminate", false).prop("checked", false);
		} else if (checkedCheckboxes.length === allCheckboxes.length) {
			selectAllCheckbox.prop("indeterminate", false).prop("checked", true);
		} else {
			selectAllCheckbox.prop("indeterminate", true);
		}
	},
});
